//! Parse Rust source code into a [`syn`] syntax tree that can be inspected
//! and transformed.
//!
//! The crate is intentionally free of `proc-macro` concerns so it can be used
//! from ordinary binaries, tests, and build scripts as well as from the
//! `ast-macros` procedural-macro facade.
//!
//! ```
//! use ast_core::{inspect, parse_source, transform};
//!
//! let mut file = parse_source("fn add(a: i32, b: i32) -> i32 { a + b }").unwrap();
//! assert_eq!(inspect::item_count(&file), 1);
//!
//! transform::rename_in_file(&mut file, "a", "x");
//! assert!(inspect::collect_identifiers(&file).contains(&"x".to_owned()));
//! ```

pub mod inspect;
pub mod transform;

use syn::File;

/// Parse a complete Rust source file into a [`syn::File`] syntax tree.
pub fn parse_source(source: &str) -> syn::Result<File> {
    syn::parse_file(source)
}

/// Parse a single Rust item (function, struct, module, ...) from source text.
pub fn parse_item(source: &str) -> syn::Result<syn::Item> {
    syn::parse_str(source)
}

//! Read-only inspection of a syntax tree, built on [`syn::visit::Visit`].

use std::collections::BTreeSet;

use syn::visit::{self, Visit};
use syn::{File, Ident};

/// Collects every identifier that appears in a syntax tree.
///
/// Names are de-duplicated and sorted, which makes the result suitable for
/// snapshot testing and for driving later transformations.
#[derive(Debug, Default, Clone)]
pub struct IdentCollector {
    names: BTreeSet<String>,
}

impl IdentCollector {
    /// Create an empty collector.
    pub fn new() -> Self {
        Self::default()
    }

    /// Iterate over the collected names in sorted order.
    pub fn names(&self) -> impl Iterator<Item = &str> {
        self.names.iter().map(String::as_str)
    }

    /// Consume the collector, returning the names in sorted order.
    pub fn into_names(self) -> Vec<String> {
        self.names.into_iter().collect()
    }

    /// Number of distinct identifiers seen so far.
    pub fn len(&self) -> usize {
        self.names.len()
    }

    /// Whether no identifiers have been seen.
    pub fn is_empty(&self) -> bool {
        self.names.is_empty()
    }
}

impl<'ast> Visit<'ast> for IdentCollector {
    fn visit_ident(&mut self, ident: &'ast Ident) {
        self.names.insert(ident.to_string());
        visit::visit_ident(self, ident);
    }
}

/// Collect every distinct identifier in `file`, sorted.
pub fn collect_identifiers(file: &File) -> Vec<String> {
    let mut collector = IdentCollector::new();
    collector.visit_file(file);
    collector.into_names()
}

/// Count the top-level items in `file`.
pub fn item_count(file: &File) -> usize {
    file.items.len()
}

//! In-place transformations of a syntax tree, built on
//! [`syn::visit_mut::VisitMut`].

use syn::visit_mut::{self, VisitMut};
use syn::{File, Ident, Item};

/// Renames every occurrence of one identifier to another.
///
/// Spans are preserved, so compiler diagnostics produced after the
/// transformation still point at the original source location.
#[derive(Debug, Clone)]
pub struct RenameIdent {
    from: String,
    to: String,
}

impl RenameIdent {
    /// Create a renamer mapping `from` to `to`.
    pub fn new(from: impl Into<String>, to: impl Into<String>) -> Self {
        Self {
            from: from.into(),
            to: to.into(),
        }
    }
}

impl VisitMut for RenameIdent {
    fn visit_ident_mut(&mut self, ident: &mut Ident) {
        if ident == self.from.as_str() {
            let span = ident.span();
            *ident = Ident::new(&self.to, span);
        }
        visit_mut::visit_ident_mut(self, ident);
    }
}

/// Rename `from` to `to` throughout a parsed file.
pub fn rename_in_file(file: &mut File, from: &str, to: &str) {
    RenameIdent::new(from, to).visit_file_mut(file);
}

/// Rename `from` to `to` throughout a single parsed item.
pub fn rename_in_item(item: &mut Item, from: &str, to: &str) {
    RenameIdent::new(from, to).visit_item_mut(item);
}

//! Procedural macros backed by [`ast_core`].
//!
//! This crate is deliberately a thin facade: all parsing, inspection, and
//! transformation lives in `ast-core`, which can be unit-tested like an
//! ordinary library.

use ast_core::{inspect, transform};
use proc_macro::TokenStream;
use proc_macro2::TokenStream as TokenStream2;
use quote::quote;
use syn::parse::Parser;
use syn::punctuated::Punctuated;
use syn::{parse_macro_input, File, Ident, Token};

/// Rename an identifier throughout the annotated item.
///
/// ```ignore
/// #[ast_macros::rename(a, x)]
/// fn add(a: i32, b: i32) -> i32 {
///     a + b
/// }
/// // expands to `fn add(x: i32, b: i32) -> i32 { x + b }`
/// ```
#[proc_macro_attribute]
pub fn rename(attr: TokenStream, item: TokenStream) -> TokenStream {
    match rename_impl(attr, item) {
        Ok(tokens) => tokens.into(),
        Err(err) => err.to_compile_error().into(),
    }
}

fn rename_impl(attr: TokenStream, item: TokenStream) -> syn::Result<TokenStream2> {
    let args = Punctuated::<Ident, Token![,]>::parse_terminated.parse(attr)?;
    let mut args = args.into_iter();
    let from = args.next().ok_or_else(|| {
        syn::Error::new(
            proc_macro2::Span::call_site(),
            "expected `#[rename(old, new)]`",
        )
    })?;
    let to = args.next().ok_or_else(|| {
        syn::Error::new(
            proc_macro2::Span::call_site(),
            "expected `#[rename(old, new)]`",
        )
    })?;

    let mut file: File = syn::parse(item)?;
    transform::rename_in_file(&mut file, &from.to_string(), &to.to_string());
    Ok(quote!(#file))
}

/// Parse the given items and expand to a human-readable summary of the
/// identifiers they contain.
///
/// Useful as a `const` initializer:
///
/// ```ignore
/// const INFO: &str = ast_macros::ast_info!(fn add(a: i32, b: i32) -> i32 { a + b });
/// ```
#[proc_macro]
pub fn ast_info(input: TokenStream) -> TokenStream {
    let file = parse_macro_input!(input as File);
    let report = format!(
        "items={} idents=[{}]",
        inspect::item_count(&file),
        inspect::collect_identifiers(&file).join(", "),
    );
    quote!(#report).into()
}

use ast_core::{inspect, parse_item, parse_source, transform};

#[test]
fn parses_and_inspects_a_file() {
    let file = parse_source("fn add(a: i32, b: i32) -> i32 { a + b }").unwrap();

    assert_eq!(inspect::item_count(&file), 1);

    let idents = inspect::collect_identifiers(&file);
    for expected in ["add", "a", "b", "i32"] {
        assert!(
            idents.contains(&expected.to_owned()),
            "missing `{expected}` in {idents:?}",
        );
    }
}

#[test]
fn parses_a_single_item() {
    let item = parse_item("struct Point { x: i32, y: i32 }").unwrap();
    assert!(matches!(item, syn::Item::Struct(_)));
}

#[test]
fn rename_replaces_every_occurrence() {
    let mut file = parse_source("fn add(a: i32, b: i32) -> i32 { a + b }").unwrap();

    transform::rename_in_file(&mut file, "a", "x");

    let idents = inspect::collect_identifiers(&file);
    assert!(idents.contains(&"x".to_owned()));
    assert!(!idents.contains(&"a".to_owned()));
    assert!(idents.contains(&"b".to_owned()));
}

#[test]
fn rename_preserves_unrelated_syntax() {
    let mut file = parse_source("fn f() -> i32 { let value = 1; value }").unwrap();

    transform::rename_in_file(&mut file, "value", "renamed");

    let idents = inspect::collect_identifiers(&file);
    assert!(idents.contains(&"renamed".to_owned()));
    assert!(!idents.contains(&"value".to_owned()));
}

#[test]
fn invalid_source_is_an_error() {
    assert!(parse_source("fn broken( {").is_err());
}

